-- 006_real_wc2026_fixtures.sql
-- Replaces placeholder seed data with real WC2026 fixture list
-- pulled from the FIFA public API on 2026-06-03.
-- DELETE-then-INSERT so re-running this migration cleanly resets the schedule.

-- Disable any existing match results to avoid stale state
DELETE FROM match_predictions WHERE match_id IN (SELECT id FROM matches);
DELETE FROM matches;

-- Reset SERIAL counter so new IDs start from 1 again
ALTER SEQUENCE matches_id_seq RESTART WITH 1;


